function volumeKey(){const g=state?.game||game;return 'sosoVolume_'+(g||'home')}
function defaultVolumeFor(g){return g==='mafia'?20:['genius','stockwar','secretvault'].includes(g)?5:20}
function syncVolumeControl(force=false){const el=$('#volume'),lab=$('#volumeValue');if(!el)return;const g=state?.game||game||'home',key='sosoVolume_'+g;const saved=localStorage.getItem(key);if(force||el.dataset.game!==g){el.dataset.game=g;el.value=saved??defaultVolumeFor(g)}if(lab)lab.textContent=el.value+'%';applyAudioVolumes()}
