$('#createBtn').onclick=()=>{if(game==='genius'&&!geniusProfile)return openGeniusAuth('create');const p=profile();if(game==='genius'&&geniusProfile){p.name=geniusProfile.name;p.avatar='💎'}else if(!p.name)return toast('닉네임을 입력해주세요.');socket.emit('createRoom',{...p,game,mode,password:$('#createPassword').value},r=>{if(r.ok)return enter(r);if(r.error==='GENIUS_AUTH_REQUIRED')return openGeniusAuth('create');toast(r.error)})};
$('#joinBtn').onclick=()=>{const p=profile();if(!p.name&&geniusProfile){p.name=geniusProfile.name;p.avatar='💎'}socket.emit('joinRoom',{...p,code:$('#codeInput').value,password:$('#joinPassword').value},r=>{if(r.ok)return enter(r);if(r.error==='GENIUS_AUTH_REQUIRED')return openGeniusAuth('join');if(!p.name)return toast('일반 게임 방은 닉네임을 입력해주세요.');toast(r.error)})};
