function home(){document.getElementById('eventPopup')?.classList.remove('show');try{stockBgm?.pause?.();vaultBgm?.pause?.();geniusLobbyBgm?.pause?.();mafiaStopAudio?.();speechSynthesis?.cancel?.()}catch{}delete localStorage.room;me=null;state=null;priv=null;rDraft=null;$('#room').classList.add('hidden');$('#home').classList.remove('hidden');$('#roomBadge').classList.add('hidden')}
socket.on('connect',()=>{if(localStorage.room&&!me)socket.emit('resumeSession',{code:localStorage.room,sessionId:sid()},r=>r.ok?enter(r):home())});
socket.on('roomState',s=>{const oldTurn=state?.rummi?.turnNumber,oldPhase=state?.phase,oldLog=state?.mafiaLog?.at(-1)||'';state=s;if(state.phase==='lobby'&&priv?.game===state.game)priv=null;if(state.game==='rummi'&&oldTurn!==state.rummi?.turnNumber)rDraft=null;syncVolumeControl();render();syncMafiaAudio();syncStockAudio();syncGeniusAudio();if(oldPhase&&oldPhase!==s.phase){if(s.phase==='mafiaNight')playSfx('night');else if(s.phase==='mafiaDay')playSfx('day');else if(['vote','mafiaVote','mafiaDefense','mafiaExecuteVote'].includes(s.phase))playSfx('vote');else if(s.phase==='stockResult'){playSfx('warning');setTimeout(()=>showEventPopup(s.stock?.news||'🚨 시장 속보','danger',2800),120)}else if(['result','mafiaResult','rummiResult','wordchainResult','stockFinal'].includes(s.phase))playSfx('win');else playSfx('start')}const nl=s.mafiaLog?.at(-1)||'';if(nl!==oldLog&&(/사망했습니다|처형되었습니다/.test(nl))){mafiaPlayGun();showEventPopup('💥 '+nl,'danger',3200)}});
