function host(){return state?.hostId===me}
function render(){if(!state)return;$('#room')?.classList.toggle('room-rummi',state.game==='rummi');$('#room')?.classList.toggle('room-wordchain',state.game==='wordchain');$('#room')?.classList.toggle('room-stockwar',state.game==='stockwar');$('#room')?.classList.toggle('room-secretvault',state.game==='secretvault');$('#room')?.classList.toggle('room-mafia',state.game==='mafia');document.querySelector('.app')?.classList.toggle('wide-game',['stockwar','secretvault','genius'].includes(state.game));$('#adminRoomPanel')?.classList.toggle('hidden',!(adminToken&&host()));$('#count').textContent=`${state.players.length}/${maxes[state.game]}`;$('#phase').textContent=phaseName[state.phase]||state.phase;$('#roomTitle').textContent=labels[state.game]+(state.round?` · ROUND ${state.round}`:'');const sb=$('#gameStatusBar');if(sb){const txt=state.game==='mafia'&&state.phase!=='lobby'?(state.mafiaDealer||phaseName[state.phase]||''):state.game==='stockwar'&&state.phase!=='lobby'?stockStageText():'';sb.textContent=txt;sb.classList.toggle('hidden',!txt)}const ds=$('#stockDealerSide');if(ds)ds.classList.toggle('hidden',state.game!=='stockwar'||state.phase==='lobby');if(state.game!=='mafia'||state.phase==='lobby')document.getElementById('mafiaSideNote')?.remove();renderPlayers();bindPlayerKick();renderSettings();renderGame();renderHost();renderTimer()}
