function roleIcon(x){return{mafia:'🔪',spy:'🕵️',police:'🚓',doctor:'🩺',soldier:'🪖',reporter:'📰',politician:'🗳️',terrorist:'💣',citizen:'🏘️',citizenTeam:'🤝',mafiaTeam:'🔪'}[x]||'❔'}
function renderPlayers(){const mafiaVisible=new Set(priv?.game==='mafia'?(priv.mafiaIds||[]):[]);const talkPhase=state.game==='liar'&&((state.mode==='normal'&&state.phase==='play')||(state.mode==='question'&&state.phase==='reveal'));const rTurn=state.game==='rummi'?state.rummi?.turnPlayerId:null,wTurn=state.game==='wordchain'?state.wordchain?.turnPlayerId:null;$('#players').innerHTML=state.players.map((p,pi)=>{const dead=state.game==='mafia'&&!p.alive,maf=state.game==='mafia'&&mafiaVisible.has(p.id),starter=talkPhase&&p.id===state.discussionStarterId,rTurnNow=state.game==='rummi'&&p.id===rTurn,wTurnNow=state.game==='wordchain'&&p.id===wTurn,wDead=state.game==='wordchain'&&state.wordchain?.eliminated?.[p.id];let status=p.connected?'<span class="status-online">● 접속 중</span>':'<span class="status-offline">접속 끊김 🔌</span>';if(p.rolePublic)status=`역할: ${role(p.rolePublic)}`;if(state.game==='rummi'&&state.rummi?.rackCounts)status=`남은 타일 <b>${state.rummi.rackCounts[p.id]??0}개</b>`;if(state.game==='wordchain'&&state.wordchain)status=`${'❤️'.repeat(state.wordchain.lives?.[p.id]||0)}${wDead?' · 💀 탈락':''}`;if(['genius','stockwar','secretvault'].includes(state.game)&&p.geniusName)status=`<span class="genius-stat">💎 가넷 ${p.geniusGarnets??0}</span><span class="genius-stat">🏆 우승 ${p.geniusWins??0}회</span>`;const starterBadge=starter?`<div class="first-speaker ${state.discussionDirection==='left'?'left':'right'}">${state.discussionDirection==='left'?'← 선':'선 →'}</div>`:'';const geniusMode=['genius','stockwar','secretvault'].includes(state.game),gi=pi%10,gcols=['#ef5350','#fdd835','#fb8c00','#42a5f5','#66bb6a','#ab47bc','#26c6da','#ec407a','#7e57c2','#8d6e63'],gicons=['●','●','●','●','●','●','●','●','●','●'];return `<div class="player ${dead?'dead':''} ${maf?'mafia-mark':''} ${starter?'first-speaker-player':''} ${rTurnNow?'rummi-current-player':''} ${wTurnNow?'wordchain-current-player':''} ${wDead?'wordchain-dead':''} ${geniusMode?'genius-player':''} ${state.game==='mafia'&&priv?.loverId===p.id?'lover-player':''}" ${geniusMode?`style="--player-color:${gcols[gi]}"`:''}>${starterBadge}<div class="face">${geniusMode?`<span class="genius-token">${gicons[gi]}</span>`:avatarHtml(p.avatar)}</div><div class="name">${esc(p.name)} ${p.id===state.hostId?'👑':''}${p.isBot?'<span class="bot-badge">🤖 BOT</span>':''}</div><div class="score">${status}</div>${dead?'<div class="death-badge">💀 사망</div>':''}${maf?'<div class="mafia-badge">🔪 마피아</div>':''}</div>`}).join('')}

function bindPlayerKick(){if(!host())return;$$('#players .player').forEach((el,i)=>el.oncontextmenu=e=>{e.preventDefault();const p=state.players[i];if(!p||p.id===me)return;if(confirm(`${p.name}님을 방에서 내보낼까요?`))socket.emit('kickPlayer',{playerId:p.id},r=>!r.ok&&toast(r.error))})}
function mafiaRoleSummary(n){if(n<5)return '5명 이상 모이면 직업 구성이 표시됩니다.';let a=[];const add=(x,c=1)=>{if(c)a.push(`${x} ${c}`)};add('🔪 마피아',n>=8?2:1);if(n>=10)add('🕵️ 스파이');add('🚓 경찰');add('🩺 의사');if(n>=6)add('🪖 군인');if(n>=7)add('📰 기자');if(n>=9)add('🗳️ 정치인');if(n>=11)add('💣 테러리스트');let used=(n>=8?2:1)+(n>=10?1:0)+2+(n>=6?1:0)+(n>=7?1:0)+(n>=9?1:0)+(n>=11?1:0);add('🏘️ 시민',n-used);return a.join(' · ')+(n>=12?' · 💘 이 중 2명은 연인':'')}
function truthGenderPanel(){const p=state.players.find(x=>x.id===me),picked=p?.gender;const ready=state.players.filter(x=>x.connected&&!x.isBot&&x.gender).length,total=state.players.filter(x=>x.connected&&!x.isBot).length;return `<div class="truth-gender-box"><div><b>나의 성별</b><span class="muted"> · 질문 구성에 참고됩니다. (${ready}/${total} 선택)</span></div><div class="gender-buttons"><button data-gender="female" class="${picked==='female'?'active':''}">♀ 여자</button><button data-gender="male" class="${picked==='male'?'active':''}">♂ 남자</button></div></div>`}
