const vaultBgm=new Audio('/secret-vault-bgm.mp3'),geniusLobbyBgm=new Audio('/genius-lobby-bgm.mp3');vaultBgm.loop=true;geniusLobbyBgm.loop=true;vaultBgm.volume=.05;geniusLobbyBgm.volume=.05;
let lastVaultDealer='';function syncGeniusAudio(){const vl=state?.game==='secretvault'&&state.phase!=='lobby',gl=state?.game==='genius'&&state.phase==='lobby',v=masterVolume();vaultBgm.volume=v;geniusLobbyBgm.volume=v;if(bgmOn&&vl)vaultBgm.play().catch(()=>{});else vaultBgm.pause();if(bgmOn&&gl)geniusLobbyBgm.play().catch(()=>{});else geniusLobbyBgm.pause();if(state?.game==='secretvault'&&state.vault?.dealer&&state.vault.dealer!==lastVaultDealer){lastVaultDealer=state.vault.dealer;try{if(!vaultBgm.paused)vaultBgm.volume=Math.min(v,.02);speakDealer(state.vault.dealer,()=>{vaultBgm.volume=masterVolume()})}catch{}}}
